import os,re,zlib,struct
root='/app/documents'
def pdf_text(data):
 out=[]
 for m in re.finditer(rb'stream\r?\n',data):
  start=m.end(); end=data.find(b'endstream',start)
  if end<0: continue
  s=data[start:end].rstrip(b'\r\n')
  candidates=[s]
  try: candidates.append(zlib.decompress(s))
  except: pass
  for x in candidates:
   if any(k in x for k in (b'BT',b'Tj',b'TJ')):
    out.append(x)
 return b'\n'.join(out)
def pdf_decode(x):
 x=re.sub(rb'\\([\\()])',rb'\1',x)
 x=re.sub(rb'\\n',b'\n',x)
 vals=[]
 for m in re.finditer(rb'\((.*?)\)\s*Tj',x,re.S): vals.append(m.group(1))
 for m in re.finditer(rb'\[(.*?)\]\s*TJ',x,re.S): vals += re.findall(rb'\((.*?)\)',m.group(1),re.S)
 return b' '.join(vals)
for n in sorted(os.listdir(root)):
 p=os.path.join(root,n); d=open(p,'rb').read()
 print('\n###',n,len(d))
 if n.lower().endswith('.pdf'):
  raw=pdf_text(d); print(pdf_decode(raw)[:5000].decode('latin1','replace'))
 else:
  # JPEG marker scan: dimensions, comments, printable runs
  pos=2
  while pos+9<len(d):
   if d[pos]!=255: pos+=1; continue
   marker=d[pos+1]; pos+=2
   if marker in (216,217): continue
   if pos+2>len(d): break
   ln=struct.unpack('>H',d[pos:pos+2])[0]
   if marker in (192,194) and pos+7<len(d):
    h,w=struct.unpack('>HH',d[pos+3:pos+7]); print('dimensions',w,h)
   if marker==254: print('COMMENT',d[pos+2:pos+ln].decode('latin1','replace'))
   pos+=ln
  runs=re.findall(rb'[ -~]{8,}',d)
  print('strings:',b' | '.join(runs[:20]).decode('latin1','replace'))
